import React, { useState } from 'react';

// Define the TodoItem interface here
interface TodoItem {
  id: number;
  text: string;
  completed: boolean;
}

// Create the OptimisticUI component function here
function OptimisticUI() {
  // Initialize the todos state here
  const [todos, setTodos] = useState<TodoItem[]>([
    { id: 1, text: 'Learn React', completed: true },
    { id: 2, text: 'Build a project', completed: false },
    { id: 3, text: 'Deploy to production', completed: false }
  ]);

  // Initialize loading state here
  const [loading, setLoading] = useState<boolean>(false);

  // Define the addTodo function here
  const addTodo = async (text: string) => {
    const newTodo: TodoItem = {
      id: Date.now(),
      text,
      completed: false
    };

    // Optimistic update
    setTodos(prev => [...prev, newTodo]);

    // Simulate API call
    try {
      setLoading(true);
      await new Promise(resolve => setTimeout(resolve, 500));
    } catch (error) {
      // Rollback on error
      setTodos(prev => prev.filter(todo => todo.id !== newTodo.id));
      console.error('Failed to add todo:', error);
    } finally {
      setLoading(false);
    }
  };

  // Define the toggleTodo function here

  return (
    <div>
      <h1>Optimistic UI Demo</h1>
    </div>
  );
}

export default OptimisticUI;

